<script setup lang="ts">import type{CascaderOption}from'@fex-design/core/cascader/types';import{ref}from'vue';import{lazyInitialOptions}from'./data';import DemoCascader from'./demo-cascader.vue';import Demo from'./demo-section.vue';const options=ref(lazyInitialOptions);async function load(path:readonly CascaderOption[]){await new Promise(resolve=>setTimeout(resolve,700));const key=String(path.at(-1)?.value);options.value=options.value.map(item=>item.value===key?{...item,children:key==='asia'?[{value:'china',label:'中国',isLeaf:false}]:[{value:'france',label:'法国'}]}:item);if(key==='china')options.value=options.value.map(item=>item.value==='asia'?{...item,children:[{value:'china',label:'中国',children:[{value:'hangzhou',label:'杭州'}]}]}:item)}</script><template><Demo title="Lazy load" description="Unresolved nodes load one path and reject duplicate requests."><DemoCascader :options="options" :load-data="load"/></Demo></template>
